-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- strict variant: fires on every write and validates every entry against NEW.plan_id
-- targets: c25c
-- scopes: all
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._reject_feature_override_above_tier()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_plan_tier text;
  v_key       text;
  v_entry     jsonb;
  v_min_tier  text;
BEGIN
  IF NEW.feature_overrides IS NULL OR NEW.feature_overrides = '{}'::jsonb THEN
    RETURN NEW;
  END IF;

  SELECT p.tier INTO v_plan_tier
    FROM public.plans p
   WHERE p.id = NEW.plan_id;

  -- jsonb_each raises 22023 when feature_overrides is not an object.
  FOR v_key, v_entry IN
    SELECT e.key, e.value FROM jsonb_each(NEW.feature_overrides) AS e
  LOOP
    v_min_tier := NULL;
    SELECT fd.min_tier INTO v_min_tier
      FROM public.feature_definitions fd
     WHERE fd.key = v_key;

    IF public._override_above_tier(v_key, v_min_tier, v_plan_tier, v_entry) THEN
      RAISE EXCEPTION 'feature_override_above_tier: % requires %; plan tier is %',
        v_key, v_min_tier, COALESCE(v_plan_tier, 'none')
        USING ERRCODE = '23514';
    END IF;
  END LOOP;

  RETURN NEW;
END
$$;
CREATE OR REPLACE TRIGGER reject_feature_override_above_tier
  BEFORE INSERT OR UPDATE ON public.organization_plans
  FOR EACH ROW
  EXECUTE FUNCTION public._reject_feature_override_above_tier();

DO $proof$
BEGIN
  IF NOT ((SELECT pg_get_triggerdef(oid) FROM pg_trigger WHERE tgrelid = 'public.organization_plans'::regclass AND tgname = 'reject_feature_override_above_tier') NOT LIKE '%UPDATE OF%' AND pg_get_functiondef('public._reject_feature_override_above_tier()'::regprocedure) NOT LIKE '%CONTINUE%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('strict trigger') AS mutation;
